                    scratch_dC[S] = alu_resultC[31:0];

                end
              CSR_SEPC :
                begin
                  csr_rvalueC = epc_qC[S];
                  if (!exceptionC)
                    epc_dC[S] = alu_resultC[31:0];

                end
              CSR_SIP, CSR_SIE : ;
              CSR_SCAUSE : ;
              CSR_STVAL : ;
              CSR_STVEC : ;
              CSR_SATP :
                begin
                  csr_rvalueC = satp_qC;
                  if (!exceptionC)
                    begin
                      satp_dC.ppn = alu_resultC[21:0];
                      satp_dC.mode = VMSupport ? alu_resultC[31] : 1'b0;
                    end

                end
              CSR_FFLAGS :
                begin
                  if (FP_EN)
                    begin
                      csr_rvalueC = {27'b0, fcsr_qC.fflags};
                      read_fcsrC = 1'b1;
                      if (!exceptionC)
                        fcsr_dC.fflags = fpnew_pkg::status_t' (alu_resultC[4:0]) ;

                    end
                  else
                    illegal_csrC = 1'b1;
                end
              CSR_FRM :
                begin
                  if (FP_EN)
                    begin
                      csr_rvalueC = {29'b0, fcsr_qC.frm};
                      read_fcsrC = 1'b1;
                      if (!exceptionC)
                        fcsr_dC.frm = fpnew_pkg::roundmode_e' (alu_resultC[2:0]) ;

                    end
                  else
                    illegal_csrC = 1'b1;
                end
              CSR_FMODE :
                begin
                  if (FP_EN)
                    begin
                      csr_rvalueC = {30'b0, fcsr_qC.fmode};
                      read_fcsrC = 1'b1;
                      if (!exceptionC)
                        fcsr_dC.fmode = fpnew_pkg::fmt_mode_t' (alu_resultC[1:0]) ;

                    end
                  else
                    illegal_csrC = 1'b1;
                end
              CSR_FCSR :
                begin
                  if (FP_EN)
                    begin
                      csr_rvalueC = {22'b0, fcsr_qC};
                      read_fcsrC = 1'b1;
                      if (!exceptionC)
                        fcsr_dC = fcsr_t' (alu_resultC[9:0]) ;

                    end
                  else
                    illegal_csrC = 1'b1;
                end
              default : csr_rvalueC = '0;
            endcase
          end
        else
          illegal_csrC = 1'b1;
      end

    if (valid_instrC)
      begin
        if (illegal_instC||illegal_csrC)
          cause_dC[M] = ILLEGAL_INSTR;

        if (ecallC)
          begin
            unique case (priv_lvl_qC)
              PrivLvlM : cause_dC[M] = ENV_CALL_MMODE;
              PrivLvlS : cause_dC[M] = ENV_CALL_SMODE;
              PrivLvlU : cause_dC[M] = ENV_CALL_UMODE;
              default : cause_dC[M] = ENV_CALL_MMODE;
            endcase
          end

        if (ebreakC)
          cause_dC[M] = BREAKPOINT;

        if (dtlb_trans_validC&&dtlb_page_faultC)
          begin
            if (is_storeC)
              cause_dC[M] = STORE_PAGE_FAULT;

            if (is_loadC)
              cause_dC[M] = LOAD_PAGE_FAULT;

          end

        if (itlb_trans_validC&&itlb_page_faultC)
          cause_dC[M] = INSTR_PAGE_FAULT;

        if (inst_addr_misalignedC)
          cause_dC[M] = INSTR_ADDR_MISALIGNED;

        if (ld_addr_misalignedC)
          cause_dC[M] = LD_ADDR_MISALIGNED;

        if (st_addr_misalignedC)
          cause_dC[M] = ST_ADDR_MISALIGNED;

        if (interruptC)
          begin
            if (meipC)
              cause_dC[M] = MEI;
            else
              if (mtipC)
                cause_dC[M] = MTI;
              else
                if (msipC)
                  cause_dC[M] = MSI;
                else
                  if (mcipC)
                    cause_dC[M] = MCI;
                  else
                    if (seipC)
                      cause_dC[M] = SEI;
                    else
                      if (stipC)
                        cause_dC[M] = STI;
                      else
                        if (ssipC)
                          cause_dC[M] = SSI;
                        else
                          if (scipC)
                            cause_dC[M] = SCI;

          end

        if (exceptionC)
          begin
            epc_dC[M] = pc_qC;
            cause_irq_dC[M] = interruptC;
            priv_lvl_dC = PrivLvlM;
            mpp_dC = priv_lvl_qC;
            pie_dC[M] = ie_qC[M];
            ie_dC[M] = 1'b0;
          end

        if (inst_data_iC==riscv_instr::MRET)
          begin
            priv_lvl_dC = mpp_qC;
            ie_dC[M] = pie_qC[M];
            pie_dC[M] = 1'b1;
            mpp_dC = snitch_pkg::PrivLvlU;
          end

        if (inst_data_iC==riscv_instr::SRET)
          begin
            priv_lvl_dC = priv_lvl_t' ({1'b0, spp_qC}) ;
            spp_dC = 1'b0;
          end

      end

    dcsr_dC.xdebugver = 4;
    dcsr_dC.zero2 = 0;
    dcsr_dC.zero1 = 0;
    dcsr_dC.zero0 = 0;
    dcsr_dC.ebreaks = 0;
    dcsr_dC.ebreaku = 0;
    dcsr_dC.stepie = 0;
    dcsr_dC.stopcount = 0;
    dcsr_dC.stoptime = 0;
    dcsr_dC.mprven = 0;
    dcsr_dC.nmip = 0;
    dcsr_dC.prv = dm::priv_lvl_t' (dm::PRIV_LVL_M) ;
  end

