    assign shift_left_resultA[i] = shift_right_resultA[31-i];
    assign shift_left_resultB[i] = shift_right_resultB[31-i];
    assign shift_left_resultC[i] = shift_right_resultC[31-i];
  end
assign shift_opaA = shift_leftA ? shift_opa_reversedA : opaA;
assign shift_opaB = shift_leftB ? shift_opa_reversedB : opaB;
assign shift_opaC = shift_leftC ? shift_opa_reversedC : opaC;
assign shift_opa_extA = {shift_opaA[31]&shift_arithmeticA, shift_opaA};
assign shift_opa_extB = {shift_opaB[31]&shift_arithmeticB, shift_opaB};
assign shift_opa_extC = {shift_opaC[31]&shift_arithmeticC, shift_opaC};
assign shift_right_result_extA = $unsigned($signed(shift_opa_extA)>>>opbA[4:0]);
assign shift_right_result_extB = $unsigned($signed(shift_opa_extB)>>>opbB[4:0]);
assign shift_right_result_extC = $unsigned($signed(shift_opa_extC)>>>opbC[4:0]);
assign shift_right_resultA = shift_right_result_extA[31:0];
assign shift_right_resultB = shift_right_result_extB[31:0];
assign shift_right_resultC = shift_right_result_extC[31:0];
logic [32:0] alu_opaA;
logic [32:0] alu_opaB;
logic [32:0] alu_opaC;
logic [32:0] alu_opbA;
logic [32:0] alu_opbB;
logic [32:0] alu_opbC;
assign adder_resultA = alu_opaA + alu_opbA;
assign adder_resultB = alu_opaB + alu_opbB;
assign adder_resultC = alu_opaC + alu_opbC;

always_comb
  begin
    alu_opaA = $signed(opaA);
    alu_opbA = $signed(opbA);
    alu_resultA = adder_resultA[31:0];
    shift_leftA = 1'b0;
    shift_arithmeticA = 1'b0;
    unique case (alu_opA)
      Sub : alu_opbA =  - $signed(opbA);
      Slt :
        begin
          alu_opbA =  - $signed(opbA);
          alu_resultA = {30'b0, adder_resultA[32]};
        end
      Ge :
        begin
          alu_opbA =  - $signed(opbA);
          alu_resultA = {30'b0, ~adder_resultA[32]};
        end
      Sltu :
        begin
          alu_opaA = $unsigned(opaA);
          alu_opbA =  - $unsigned(opbA);
          alu_resultA = {30'b0, adder_resultA[32]};
        end
      Geu :
        begin
          alu_opaA = $unsigned(opaA);
          alu_opbA =  - $unsigned(opbA);
          alu_resultA = {30'b0, ~adder_resultA[32]};
        end
      Sll :
        begin
          shift_leftA = 1'b1;
          alu_resultA = shift_left_resultA;
        end
      Srl : alu_resultA = shift_right_resultA;
      Sra :
        begin
          shift_arithmeticA = 1'b1;
          alu_resultA = shift_right_resultA;
        end
      LXor : alu_resultA = opaA^opbA;
      LAnd : alu_resultA = opaA&opbA;
      LNAnd : alu_resultA =  (~ opaA ) &opbA;
      LOr : alu_resultA = opaA|opbA;
      Eq :
        begin
          alu_opbA =  - $signed(opbA);
          alu_resultA = ~|adder_resultA;
        end
      Neq :
        begin
          alu_opbA =  - $signed(opbA);
          alu_resultA = |adder_resultA;
        end
      BypassA :
        begin
          alu_resultA = opaA;
        end
      default : alu_resultA = adder_resultA[31:0];
    endcase
  end

always_comb
  begin
    alu_opaB = $signed(opaB);
    alu_opbB = $signed(opbB);
