      Srl : alu_resultB = shift_right_resultB;
      Sra :
        begin
          shift_arithmeticB = 1'b1;
          alu_resultB = shift_right_resultB;
        end
      LXor : alu_resultB = opaB^opbB;
      LAnd : alu_resultB = opaB&opbB;
      LNAnd : alu_resultB =  (~ opaB ) &opbB;
      LOr : alu_resultB = opaB|opbB;
      Eq :
        begin
          alu_opbB =  - $signed(opbB);
